const EXE="/workspace/dataset/test16_executable";
function t(label,argv0){
 const r=spawnSync(EXE,[], {argv0, encoding:"utf8"});
 console.log(JSON.stringify({label,argv0,code:r.status,stdout:r.stdout,stderr:r.stderr}));
}
t("argv0 empty","");
t("argv0 plain","foo");
t("argv0 trailing slash","some/dir/");
t("argv0 deep path","/x/y/z/myprog");
t("argv0 spaces","my prog name");
t("argv0 dotdot","..");
t("argv0 dot",".");
t("argv0 long","A".repeat(60));
'

